 void ItemIcon(Transform parent,MultiFPS.Gameplay.RiftCombat.RiftLootItemDefinition item,int potion,float x,float y,float size){var root=W.Rect(parent,"Item icon",x,y,size,size);var bg=root.gameObject.AddComponent<RiftHUDChrome>();bg.Cut=4;bg.color=new Color(.035f,.027f,.05f);bg.Border=new Color(.5f,.45f,.61f);bg.raycastTarget=false;if(item&&item.Weapon)RiftItemArt.Place(root,item.Weapon.Model,3,3,size-6);else{var icon=W.Rect(root,"Existing potion symbol",size*.25f,size*.1f,size*.5f,size*.75f).gameObject.AddComponent<RiftHUDGraphic>();icon.Shape=HUDShape.Potion;icon.color=potion==0?new Color(.85f,.15f,.23f):new Color(.76f,.27f,.61f);icon.raycastTarget=false;}}
